import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Media Playback (libmpv)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/media.md","filePath":"guide/media.md","lastUpdated":1790847150000}'),n={name:"guide/media.md"};function l(o,e,d,p,r,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="media-playback-libmpv" tabindex="-1">Media Playback (libmpv) <a class="header-anchor" href="#media-playback-libmpv" aria-label="Permalink to &quot;Media Playback (libmpv)&quot;">​</a></h1><p>On desktop, NeoFlux can render video through <a href="https://mpv.io" target="_blank" rel="noreferrer">libmpv</a> using mpv&#39;s <strong>render API</strong>. Instead of putting mpv in its own window, the renderer is driven by NeoFlux&#39;s existing OpenGL context so each decoded video frame becomes a normal GL texture that a widget can draw.</p><div class="warning custom-block"><p class="custom-block-title">Optional feature</p><p>Desktop video support is gated behind the <code>NEOFLUX_HAS_MPV</code> compile definition and requires libmpv development files at build time. Without it, the media APIs are not compiled in and the rest of the framework works unchanged.</p></div><h2 id="how-it-fits-the-two-layer-model" tabindex="-1">How it fits the two-layer model <a class="header-anchor" href="#how-it-fits-the-two-layer-model" aria-label="Permalink to &quot;How it fits the two-layer model&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+------------------ Application thread ------------------+</span></span>
<span class="line"><span>|  MediaPlayer widget                                     |</span></span>
<span class="line"><span>|    mpv_command(mpv, &quot;loadfile&quot;, path)                   |</span></span>
<span class="line"><span>|    play / pause / seek                                  |</span></span>
<span class="line"><span>+--------------------------------------------------------+</span></span>
<span class="line"><span>                     |</span></span>
<span class="line"><span>                     |  mpv render context &quot;need update&quot; callback</span></span>
<span class="line"><span>                     v</span></span>
<span class="line"><span>+------------------ Render thread (owns GL context) -----+</span></span>
<span class="line"><span>|  mpv_render_context_render()  -&gt; writes into a GL FBO    |</span></span>
<span class="line"><span>|  the resulting frame becomes a GL texture              |</span></span>
<span class="line"><span>|  that a Texture widget draws like any other command     |</span></span>
<span class="line"><span>+--------------------------------------------------------+</span></span></code></pre></div><ol><li>The <strong>mpv render context</strong> is created against the same OpenGL context the render thread already owns (the GLFW/WGL context on desktop).</li><li>mpv decodes the file asynchronously and calls an &quot;update&quot; callback when a new frame is ready. That callback asks the render thread to redraw.</li><li>On the render thread, <code>mpv_render_context_render()</code> draws the decoded frame into an off-screen GL framebuffer/texture. NeoFlux then emits an ordinary &quot;draw texture&quot; render command for that texture, so video composites exactly like any other widget (backgrounds, text overlays, clipping).</li></ol><p>Because all mpv rendering happens on the render thread where the GL context is current, no context migration is needed.</p><h2 id="playing-a-real-file" tabindex="-1">Playing a real file <a class="header-anchor" href="#playing-a-real-file" aria-label="Permalink to &quot;Playing a real file&quot;">​</a></h2><p>Playback takes a real media file path (or any URL mpv supports):</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Built only when NEOFLUX_HAS_MPV is on.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MediaPlayer player;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">player.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tests/data/sample.mp4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">player.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Play</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Control uses mpv commands under the hood:</p><table tabindex="0"><thead><tr><th>Action</th><th>mpv command</th></tr></thead><tbody><tr><td>Load a file</td><td><code>loadfile &lt;path&gt; replace</code></td></tr><tr><td>Play / pause</td><td><code>set pause no</code> / <code>set pause yes</code></td></tr><tr><td>Seek</td><td><code>seek &lt;seconds&gt; absolute</code></td></tr><tr><td>Stop</td><td><code>stop</code></td></tr></tbody></table><h2 id="sample-test-clip" tabindex="-1">Sample test clip <a class="header-anchor" href="#sample-test-clip" aria-label="Permalink to &quot;Sample test clip&quot;">​</a></h2><p>The repo ships <code>tests/data/sample.mp4</code> as a short, self-contained clip used by the media tests and demos. Point a <code>MediaPlayer</code> at it to exercise playback end to end without downloading external assets:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\bin\\</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">media_demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.exe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logtostderr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verbose_logging</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Use --logtostderr</p><p>mpv prints a lot of diagnostic output. Running with <code>--logtostderr</code> makes it visible in the terminal (examples are otherwise GUI-subsystem with no console).</p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>libmpv (<code>mpv/client.h</code>, <code>mpv/render_gl.h</code>) available at build time.</li><li>The desktop GL path (<code>--render_backend=gl</code>), since the render context wraps an OpenGL context.</li><li>A decode path for the container/codecs your files use (system ffmpeg/libav bundled with your mpv build).</li></ul><h2 id="what-could-not-be-verified-in-this-checkout" tabindex="-1">What could not be verified in this checkout <a class="header-anchor" href="#what-could-not-be-verified-in-this-checkout" aria-label="Permalink to &quot;What could not be verified in this checkout&quot;">​</a></h2><p>The <code>docs/bilingual</code> worktree does not currently contain the <code>MediaPlayer</code> sources or the <code>NEOFLUX_HAS_MPV</code> CMake wiring. This page documents the intended desktop media architecture described for the project; confirm the exact class names and CMake option against the media sources in the main checkout before shipping a product build.</p>`,20)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
